/// <summary>
/// The <c>AVABPInfoContract</c> class is the data contract class for <c>BP-Info</c>
/// </summary>
[
    DataContractAttribute,
    SysOperationContractProcessingAttribute(classStr(AVABPInfoUIBuilder)),
    SysOperationGroupAttribute('Categories',        literalStr("@NDX:NXABPInfoCategories"),         '2'), // , FormArrangeMethod::Vertical),
    SysOperationGroupAttribute('DataGeneration',    literalStr("@NDX:NXAParametersDataGeneration"), '3'),
    SysOperationGroupAttribute('SendInfomation',    literalStr("@NDX:NXAParametersSending"),        '4')
]
class AVABPInfoContract implements  SysOperationValidatable,
                                    SysOperationInitializable
{
    Args                                    frmArgs;
    AVABPInfoFromKCS_KBVBuildingProjectID   frmKCS_KBVBuildingProjectID;
    KCS_KBVParameters                       frmKCS_KBVParameters;

    boolean                                 lJobMode;

    AVABPInfoNewBuildingProjects            frmAVABPInfoNewBuildingProjects;
    AVABPInfoNewRequests                    frmAVABPInfoNewRequests;
    AVABPInfoNewRequestsRICO                frmAVABPInfoNewRequestsRICO;
    AVABPInfoNewQuotations                  frmAVABPInfoNewQuotations;
    AVABPInfoChangedQuotations              frmAVABPInfoChangedQuotations;
    AVABPInfoChangedBuildingProjects        frmAVABPInfoChangedBuildingProjects;
    AVABPInfoNewChangedActivities           frmAVABPInfoNewChangedActivities;

    AVABPInfoBuildNewData                   frmAVABPInfoBuildNewData;
    AVABPInfoDateTime                       frmAVABPInfoDateTime;
    AVABPInfoFromKCS_KBVBuildingProjectID   frmFromKCS_KBVBuildingProjectID;

    AVABPInfoSendInfo                       frmAVABPInfoSendInfo;
    Email                                   frmAVABPInfoTestEmailTo;
    HCMWorkerRecId                          frmHCMWorkerRecId;


}

