/// <summary>
///    AVA <c>validate</c> method.
/// </summary>
/// <returns>
///    Value <c>boolean</c> as result
/// </returns>
public boolean validate()
{
    boolean retVal;

    retVal = true;

    return retVal;
}

/// <summary>
///    AVA <c>initialize</c> method.
/// </summary>
public void initialize()
{
    Common                      locCommon;
    KCS_KBVBuildingProjectTable locKCS_KBVBuildingProjectTable;

    if (frmArgs && frmArgs.record())
    {
        locCommon = frmArgs.record();
        if(     locCommon.RecId
            &&  locCommon.TableId == tableNum(KCS_KBVBuildingProjectTable))
        {
            locKCS_KBVBuildingProjectTable = locCommon;

            frmKCS_KBVBuildingProjectID =  locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;
        }
    }

    frmKCS_KBVParameters                = KCS_KBVParameters::find();

    lJobMode                            = false;

    frmAVABPInfoNewBuildingProjects     = false;
    frmAVABPInfoNewRequests             = false;
    frmAVABPInfoNewRequestsRICO         = false;
    frmAVABPInfoNewQuotations           = false;
    frmAVABPInfoChangedBuildingProjects = false;
    frmAVABPInfoChangedQuotations       = false;
    frmAVABPInfoNewChangedActivities    = false;

    frmAVABPInfoBuildNewData            = false;
    if(frmKCS_KBVParameters.BVInfoTestEmail)
    {
        frmAVABPInfoSendInfo                = true;
        frmAVABPInfoTestEmailTo             = frmKCS_KBVParameters.BVInfoTestEmail;
    }
    else
    {
        frmAVABPInfoSendInfo                = false;
        frmAVABPInfoTestEmailTo             = '';
    }

    //frmKCS_KBVBuildingProjectID         = '';
    frmHCMWorkerRecId                   = HcmWorkerLookUp::currentWorker();
    frmAVABPInfoDateTime                = KCS_KBVParameters::find().NDX_KBVInfoDateTime; //DateTimeUtil::getSystemDateTime();

}

